const causes=[{id:'safe',name:'Her Safe Place',label:'Safety & a fresh start',art:'hope-nest',summary:'A safe place to land. A chance to begin again.',story:'A sample women-led charity helping women find safety, stability, and a fresh start after domestic abuse.',support:'Emergency accommodation, practical essentials, and one-to-one support as women rebuild their lives.',votes:86},{id:'girls',name:'Open Doors for Girls',label:'Education & opportunity',art:'wisdom-scroll',summary:'Help a girl stay in school and see a bigger future.',story:'A sample charity removing everyday barriers that keep girls from continuing their education.',support:'School supplies, transport assistance, and mentoring that helps girls keep learning.',votes:64},{id:'mothers',name:'The Motherhood Fund',label:'Care for mothers',art:'relationship-hands',summary:'Care for the woman who cares for everyone.',story:'A sample charity offering practical care and connection for mothers experiencing financial hardship.',support:'Baby essentials, meals, and a network of local support.',votes:50}];
const localChurch={id:'church',name:'Grace Church Pantry',label:'Local church outreach',art:'community',summary:'Practical care for women and families in the neighborhood.',story:'A fictional local church project offering a welcoming place to find practical help and connection.',support:'Community meals, essential groceries, and women’s support gatherings led by local volunteers.',votes:36};
const allCauses=[...causes,localChurch];
let vote=null,view='month',api,candidate=null,editingSuggestion=null,suggestionType='Charity',savedSuggestion=null;
let suggestions=[];try{suggestions=JSON.parse(localStorage.getItem('her-crown-cause-suggestions-v1')||'[]');if(!Array.isArray(suggestions))suggestions=[]}catch{}
const escapeCopy=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const photos={safe:'community-photos/6646918.jpg',girls:'community-photos/5212345.jpg',mothers:'community-photos/3875225.jpg',church:'community-photos/208315.jpg'};
function detailArt(c){return variant==='gallery'?`<img class="cv-detail-photo" src="${photos[c.id]}" alt="Representative stock photograph">`:`<img src="illustration-pack/${c.art}.png" alt="">`}
const variant='gallery';
try{vote=localStorage.getItem('her-crown-community-ballot-v2');if(!allCauses.some(c=>c.id===vote))vote=null}catch{}
const dots='<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><circle cx="5" cy="12" r="1.7"/><circle cx="12" cy="12" r="1.7"/><circle cx="19" cy="12" r="1.7"/></svg>';
function rows(renderIcon,ballot=false){const total=236+(vote?1:0);return `<div class="discovery-stack discover-editorial-list">${allCauses.map(c=>{const chosen=c.id===vote,selected=c.id===candidate,n=c.votes+(chosen?1:0),pct=Math.round(n/total*100);return `<article class="verse-card discover-entry"><button class="discover-entry-open" ${ballot?`data-cv-select="${c.id}" aria-pressed="${selected}" aria-label="Select ${c.name}"`:`data-cv-story="${c.id}" aria-label="Read about ${c.name}"`}><span class="discover-thumb"><img src="illustration-pack/${c.art}.png" alt="" width="88" height="94"></span><span class="discover-entry-copy"><h2>${c.name}</h2><span class="discover-entry-reference">${c.label}</span><span class="discover-entry-topic">${ballot?(selected?'Selected for your vote':'November nominee'):vote?`${chosen?'Your vote':'Sample results'} · ${pct}%`:'November nominee'}</span></span></button><button class="discover-entry-more ${ballot?'cv-select-control':''}" ${ballot?`data-cv-select="${c.id}" aria-label="${selected?'Selected':'Select'} ${c.name}" aria-pressed="${selected}"`:`data-cv-menu="${c.id}" aria-label="Options for ${c.name}"`}>${ballot?renderIcon(selected?'check':'chevron'):dots}</button></article>`}).join('')}</div>`}
function feature(renderIcon){if(variant==='ballot')return `<section class="discover-feature featured-passage cv-ballot-intro"><div class="featured-passage-copy"><h2>Where should<br>care go next?</h2><p>Four causes. One vote.<br>Choose what’s close to your heart.</p></div></section>`;
if(variant==='spotlight')return `<section class="discover-feature featured-passage"><div class="featured-passage-copy"><h2>Care for<br>the one<br>who cares.</h2><p>Meet The Motherhood Fund,<br>one of this month’s nominees.</p><button class="featured-passage-action" data-cv-story="mothers">Read her story ${renderIcon('arrow')}</button></div><img class="featured-passage-art" src="illustration-pack/relationship-hands.png" alt="" width="180" height="182"></section>`;
return `<section class="discover-feature featured-passage" aria-label="Community giving"><div class="featured-passage-copy"><h2>Her future.<br>Our purpose.</h2><p>Choose a cause supporting<br>women and girls this month.</p><button class="featured-passage-action" data-cv-rules>How it works ${renderIcon('arrow')}</button></div><img class="featured-passage-art" src="illustration-pack/gratitude-basket.png" alt="" width="180" height="182"></section>`}
function suggestionPrompt(){return `<div class="cv-suggest-prompt"><div><h3>A cause close to home?</h3><p>Nominate a charity, local church, or community project for December’s vote.</p></div><button class="textbtn" data-cv-suggest>Suggest a cause ${api?.icon('arrow')||'→'}</button>${suggestions.length?`<button class="textbtn cv-suggestion-count" data-cv-suggestions>Your suggestions · ${suggestions.length}</button>`:''}</div>`}
function gallery(renderIcon){return `<section class="cv-unified-intro"><div class="cv-giving-total" aria-label="$7,350 donated so far"><p><strong>$7,350</strong><span>donated so far</span></p><small>30% of revenue goes toward donations.</small></div><h2>A little care,<br>close to home.</h2><p>Each month, our community votes for a cause supporting women and girls. Explore charities and local church projects, then choose one.</p><button class="featured-passage-action" data-cv-suggest>Suggest a local cause ${renderIcon('arrow')}</button></section><div class="discover-section-heading"><h2>November’s ballot</h2><span>4 causes · 1 vote</span></div><div class="cv-photo-grid">${allCauses.map(c=>`<article class="cv-photo-cause"><div class="cv-photo-frame"><button class="cv-photo-open" data-cv-story="${c.id}" aria-label="View ${c.name} story"><span class="cv-photo-stack"><img src="${photos[c.id]}" alt="Representative stock photograph"></span></button><button class="cv-photo-vote ${vote===c.id?'is-voted':''}" data-cv-confirm="${c.id}" aria-label="${vote===c.id?'Your vote for':'Vote for'} ${c.name}">${vote===c.id?renderIcon('check'):''}<span>${vote===c.id?'Voted':'Vote'}</span></button></div><button class="cv-photo-caption" data-cv-story="${c.id}" aria-label="Read about ${c.name}"><h3>${c.name}</h3><span class="cv-photo-category">${c.label}</span></button></article>`).join('')}</div><p class="cv-footnote">${vote?'Your November vote is saved. You can change it before November 30.':'One member. One vote. You can change your choice until November 30.'}</p><p class="cv-stock-note">Stock photos illustrate fictional causes; they do not identify charity beneficiaries.</p>`}
export function communitySubpageTitle(){return view==='suggest'?'Suggest a cause':view==='suggestions'?'Your suggestions':view==='suggestion-saved'?'Suggestion saved':''}

export function communityMarkup(renderIcon){if(view==='suggest')return `<section class="cv-suggestion-page">${nominationForm(editingSuggestion,suggestionType)}</section>`;if(view==='suggestions')return `<section class="cv-suggestion-page">${suggestionListMarkup()}</section>`;if(view==='suggestion-saved')return `<section class="cv-suggestion-page">${suggestionSuccess(savedSuggestion)}</section>`;const ballot=variant==='ballot';return `<div class="community-voting" data-community-version="${variant}"><div class="filterbar discover-editorial-tabs" aria-label="Community sections"><button data-cv-tab="month" class="${view==='month'?'selected':''}" aria-pressed="${view==='month'}">This month</button><button data-cv-tab="impact" class="${view==='impact'?'selected':''}" aria-pressed="${view==='impact'}">Our impact</button></div>${view==='month'?`${variant==='gallery'?gallery(renderIcon):`${feature(renderIcon)}<div class="discover-section-heading"><h2>${ballot?'Your monthly vote':variant==='spotlight'?'Meet all three nominees':'This month’s causes'}</h2><span>November 2026 · One vote</span></div>${rows(renderIcon,ballot)}${ballot?`<div class="cv-ballot-actions"><button class="primary" data-cv-confirm="${candidate||''}" ${candidate?'':'disabled'}>${candidate===vote&&vote?'View my selected cause':vote?'Change my vote':'Continue with my vote'}</button><button class="textbtn" ${candidate?`data-cv-story="${candidate}"`:'data-cv-rules'}>${candidate?'Read this charity’s story':'How voting works'}</button></div>`:''}<p class="cv-footnote">${vote?'Your vote is saved. You can change it before November 30.':ballot?'You can change your choice before November 30.':'Read each story, then choose a cause to vote for.'}</p>`}${variant==='gallery'?(suggestions.length?`<div class="cv-suggestion-footer"><button class="textbtn" data-cv-suggestions>Your suggestions · ${suggestions.length}</button></div>`:''):suggestionPrompt()}`:`<section class="discover-feature featured-passage"><div class="featured-passage-copy"><h2>Our story starts<br>with your voice.</h2><p>See the selected charity and its updates after our first voting round.</p><button class="featured-passage-action" data-cv-tab="month">Explore the causes ${renderIcon('arrow')}</button></div><img class="featured-passage-art" src="${variant==='gallery'?photos.safe:'illustration-pack/community.png'}" alt="" width="180" height="182"></section>`}<p class="cv-sample">Concept preview · fictional charities and sample results</p></div>`}

function close(){document.querySelector('#detail-dialog')?.close()}
function story(id){const c=allCauses.find(x=>x.id===id);api.showDialog(`<div class="cv-detail">${detailArt(c)}<p class="overline">${c.label}</p><h2 id="dialog-title">${c.name}</h2><p>${c.story}</p><h3>What support could look like</h3><p>${c.support}</p><button class="primary" data-cv-confirm="${c.id}" ${vote===c.id?'disabled':''}>${vote===c.id?'You’ve voted for this cause':'Vote for this cause'}</button><p class="cv-sample">Fictional organization for design review.</p></div>`)}
function menu(id){const c=allCauses.find(x=>x.id===id);api.showDialog(`<div class="discover-passage-menu"><h2 id="dialog-title">${c.name}</h2><div class="study-options"><button data-cv-story="${id}">${api.icon('book')}<span>Read their story</span>${api.icon('chevron')}</button><button data-cv-confirm="${id}">${api.icon('check')}<span>${vote===id?'Your selected cause':vote?'Move my vote here':'Vote for this cause'}</span>${api.icon('chevron')}</button></div></div>`)}
function confirm(id){if(vote===id){story(id);return}const c=allCauses.find(x=>x.id===id);api.showDialog(`<div class="cv-detail">${detailArt(c)}<h2 id="dialog-title">${vote?'Change your vote?':'Your monthly vote'}</h2><p>${vote?'Move your vote to':'Cast your vote for'} ${c.name}?</p><p>You have one vote. You can change it until November 30.</p><button class="primary" data-cv-cast="${c.id}">${vote?'Change my vote':'Confirm my vote'}</button><button class="secondary" data-cv-cancel>Keep exploring</button><p class="cv-sample">Sample ballot. This does not make a donation or authorize a payment.</p></div>`)}
function rules(){api.showDialog(`<div class="cv-detail"><h2 id="dialog-title">A shared choice</h2><p>Each month, explore causes supporting women and girls. Choose the one closest to your heart.</p><h3>One member, one vote</h3><p>Every vote counts equally. Results appear after you vote.</p><h3>You can change your mind</h3><p>Your vote can move to another cause until November 30.</p><h3>After the round closes</h3><p>The selected charity and its update would appear in Our impact.</p><p class="cv-sample">Fictional charities and sample results. Funding, verification and tie rules must be defined before launch.</p><button class="primary" data-cv-cancel>Done</button></div>`)}
export function bindCommunityVoting(options){api=options;document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-cv-home'))navigateCommunity('month',false);if(b.hasAttribute('data-cv-suggest'))suggestForm(null,b.dataset.suggestType);if(b.hasAttribute('data-cv-suggestions'))suggestionList();if(b.dataset.cvEdit)suggestForm(b.dataset.cvEdit);if(b.dataset.cvTab){view=b.dataset.cvTab;api.rerender();window.scrollTo(0,0)}if(b.dataset.cvSelect){candidate=b.dataset.cvSelect;api.rerender();document.querySelector(`[data-cv-select="${candidate}"]`)?.focus()}if(b.dataset.cvStory)story(b.dataset.cvStory);if(b.dataset.cvMenu)menu(b.dataset.cvMenu);if(b.dataset.cvVote)confirm(b.dataset.cvVote);if(b.dataset.cvConfirm)confirm(b.dataset.cvConfirm);if(b.dataset.cvCast){vote=b.dataset.cvCast;try{localStorage.setItem('her-crown-community-ballot-v2',vote)}catch{}close();api.rerender();api.toast('Your vote is saved. Thank you for showing up.')}if(b.hasAttribute('data-cvCancel')||b.hasAttribute('data-cv-cancel'))close();if(b.hasAttribute('data-cv-rules'))rules()})}

function nominationForm(id=null,type='Charity'){
const item=suggestions.find(x=>x.id===id)||{name:'',type,location:'',website:'',reason:''};
return `<div class="cv-detail cv-suggest-form"><p class="overline">FOR DECEMBER’S BALLOT</p><h2 id="dialog-title">A cause you<br>believe in.</h2><p>Tell us about a charity, local church, or community project supporting women and girls.</p><form id="cv-nomination" novalidate data-edit="${id||''}"><label for="cv-cause-name">Name of the cause<input id="cv-cause-name" name="name" maxlength="90" placeholder="Charity, church, or project name" value="${escapeCopy(item.name)}" autocomplete="organization" required></label><label for="cv-cause-type">Type<select id="cv-cause-type" name="type">${['Charity','Local church','Community project'].map(x=>`<option ${x===item.type?'selected':''}>${x}</option>`).join('')}</select></label><label for="cv-cause-location">City or town <span>Optional</span><input id="cv-cause-location" name="location" maxlength="90" value="${escapeCopy(item.location)}" placeholder="Where is it based?"></label><label for="cv-cause-website">Website <span>Optional</span><input id="cv-cause-website" name="website" type="url" inputmode="url" value="${escapeCopy(item.website)}" placeholder="https://" autocapitalize="off" autocomplete="url"></label><label for="cv-cause-reason">Why this cause?<textarea id="cv-cause-reason" name="reason" maxlength="500" rows="3" placeholder="How does it support women or girls?" required>${escapeCopy(item.reason)}</textarea></label><p id="cv-suggestion-error" role="alert"></p><button class="primary" type="submit">${id?'Save changes':'Save my suggestion'}</button><p class="cv-sample">Suggestions are considered before joining a ballot. This preview saves your entry on this device; it does not send it to a team.</p></form></div>`
}
function navigateCommunity(page,push=true){close();view=page;const url=new URL(location.href);if(page==='month')url.searchParams.delete('communityPage');else url.searchParams.set('communityPage',page);history[push?'pushState':'replaceState']({communityPage:page},'',url);api.rerender();window.scrollTo(0,0);const heading=document.querySelector('.app-header h1');heading?.setAttribute('tabindex','-1');heading?.focus({preventScroll:true})}
function suggestForm(id=null,type='Charity'){editingSuggestion=id;suggestionType=type||'Charity';navigateCommunity('suggest')}
function suggestionList(){navigateCommunity('suggestions')}
function suggestionListMarkup(){return `<div class="cv-detail"><h2>Close to your heart.</h2><p>Your suggestions for December’s shortlist.</p><div class="study-options">${suggestions.map(item=>`<button data-cv-edit="${escapeCopy(item.id)}"><span><strong>${escapeCopy(item.name)}</strong><small>${escapeCopy(item.type)}${item.location?' · '+escapeCopy(item.location):''}<br>Saved in this preview</small></span>${api.icon('chevron')}</button>`).join('')}</div><button class="primary" data-cv-suggest>Suggest another cause</button></div>`}
function suggestionSuccess(item){return `<div class="cv-detail"><p class="overline">FOR DECEMBER’S BALLOT</p><h2>Thank you for<br>bringing it here.</h2><p><strong>${escapeCopy(item.name)}</strong> is saved as your suggestion.</p><p>Suggestions would be reviewed before next month’s shortlist is selected. A nomination does not guarantee a place on the ballot.</p><p class="cv-sample">Saved locally in this prototype. Nothing has been sent.</p><button class="primary" data-cv-suggestions>View my suggestions</button><button class="secondary" data-cv-home>Back to Community</button></div>`}
window.addEventListener('popstate',()=>{const page=new URLSearchParams(location.search).get('communityPage');view=['suggest','suggestions','suggestion-saved'].includes(page)?page:'month';api?.rerender();window.scrollTo(0,0)});
document.addEventListener('submit',e=>{if(e.target.id!=='cv-nomination')return;e.preventDefault();const form=e.target,values=new FormData(form);const item=Object.fromEntries([...values].map(([k,v])=>[k,String(v).trim()]));const error=form.querySelector('#cv-suggestion-error');const fail=(message,id)=>{error.textContent=message;form.querySelector('#'+id).focus()};if(item.name.length<2){fail('Please add the name of the cause.','cv-cause-name');return}if(item.reason.length<10){fail('Tell us a little more about why you’re suggesting it.','cv-cause-reason');return}if(item.website){try{const url=new URL(item.website);if(!['https:','http:'].includes(url.protocol))throw Error();item.website=url.href}catch{fail('Enter a full website address starting with https://, or leave it blank.','cv-cause-website');return}}item.id=form.dataset.edit||String(Date.now());const existing=suggestions.findIndex(x=>x.id===item.id);const next=[...suggestions];if(existing>=0)next[existing]=item;else next.unshift(item);try{localStorage.setItem('her-crown-cause-suggestions-v1',JSON.stringify(next));suggestions=next}catch{error.textContent='We couldn’t save your suggestion on this device. Please try again.';return}savedSuggestion=item;navigateCommunity('suggestion-saved',false)});
